# Viva — slot D8: benign tumours & cysts (8 cases)
# Own words. Topics guided by the previous-year question book (Sahana P Raju) — tumour chapter (classification of
# benign tumours, dermatofibroma, painful tumours, eccrine tumours), neonatal chapter (classify milia), CTD chapter
# (colloid milium), acne chapter (sebaceous variations), dermatosurgery (cyst excision, keloid/scar management);
# facts checked with IADVL 5e.
PYQ = "Previous-year PG question papers (Sahana P Raju, Solved Papers Dermatology)"
IA = "IADVL Textbook of Dermatology 5e"

D = [
dict(case="Acrochordon (skin tag)", src=f"{PYQ}; {IA} (Benign fibrous tumours)",
 qa=[
 ("What is an acrochordon?", ["Common benign soft fibroepithelial polyp (skin tag, soft fibroma) — small, soft, skin-coloured or pigmented, pedunculated papules on neck, axillae, groin, eyelids, inframammary; middle age, obese, pregnant women"]),
 ("Associations.", ["Obesity, insulin resistance/type 2 diabetes, metabolic syndrome, acanthosis nigricans, dyslipidaemia, pregnancy (hormonal), acromegaly, PCOS; Birt–Hogg–Dubé (fibrofolliculomas mistaken for tags), Cowden; association with colonic polyps is debated"]),
 ("Histopathology.", ["Polypoid lesion with loose fibrovascular stroma (collagen and dilated vessels), thin overlying epidermis (may be acanthotic/papillomatous), no adnexa; fat in larger lesions (fibrolipoma)"]),
 ("Differential diagnosis.", ["Pedunculated seborrhoeic keratosis, intradermal naevus, neurofibroma (button-hole sign), molluscum, filiform wart, fibroepithelioma of Pinkus, pedunculated BCC/melanoma (rare — remove and send if atypical), fibrofolliculomas (BHD)"]),
 ("Treatment.", ["Snip excision with sterile scissors (with or without local anaesthetic) and haemostasis, cryotherapy, radiofrequency/electrocautery, ligation for larger ones; send atypical lesions for histopathology", "Screen for diabetes/metabolic syndrome in patients with multiple tags (especially with AN)"]),
 ],
 spot=["Multiple soft pedunculated neck papules with AN — skin tags; check sugar"]),

dict(case="Seborrhoeic keratosis", src=f"{PYQ}; {IA} (Benign epidermal tumours)",
 qa=[
 ("What is seborrhoeic keratosis (SK)?", ["Commonest benign epidermal tumour of middle-aged and elderly; well-demarcated, 'stuck-on', verrucous, waxy, light-brown to black papules/plaques on trunk, face, scalp, limbs (not palms/soles); FGFR3 and PIK3CA activating mutations; familial tendency"]),
 ("Clinical variants.", ["Common, reticulated (adenoid), irritated/inflamed, clonal, dermatosis papulosa nigra (multiple small dark papules on face of dark-skinned people — very common in India, from adolescence), stucco keratosis (grey-white keratotic papules on ankles/legs of elderly), melanoacanthoma, inverted follicular keratosis, flat SK (resembles solar lentigo)"]),
 ("Dermoscopy.", ["Comedo-like openings, milia-like cysts, cerebriform (brain-like) pattern with fissures and ridges ('fat fingers'), hairpin vessels with white halo, sharp moth-eaten border, network-like structures"]),
 ("Histopathology.", ["Exophytic acanthotic proliferation of basaloid keratinocytes above the level of surrounding epidermis ('string sign'), horn cysts and pseudo-horn cysts, papillomatosis, variable melanin", "Types: acanthotic (commonest), hyperkeratotic, reticulated, clonal (Borst–Jadassohn phenomenon — intraepidermal nests), irritated (squamous eddies), melanoacanthoma"]),
 ("Write short notes on Borst–Jadassohn phenomenon (PYQ).", ["Intraepidermal nests of morphologically distinct cells within the epidermis — 'intraepidermal epithelioma'; seen in clonal SK, hidroacanthoma simplex (intraepidermal poroma), Bowen's disease (clonal), Paget's disease, melanoma in situ"]),
 ("What is the sign of Leser–Trélat?", ["Sudden eruption of multiple SKs or rapid increase in size/number — paraneoplastic sign of internal malignancy (GI adenocarcinoma — stomach, colon; lymphoma), often with malignant AN and pruritus; also reported with erythroderma, pregnancy, HIV, drugs (cytarabine — inflamed SKs)"]),
 ("Differential diagnosis.", ["Melanoma (especially pigmented, irritated SK), pigmented BCC, solar lentigo, melanocytic naevus, wart, AK, SCC (irritated SK), dermatosis papulosa nigra vs skin tags/syringomas"]),
 ("Treatment.", ["Reassurance — benign, no malignant potential", "Removal for irritation, cosmetic reasons or diagnostic doubt: cryotherapy, curettage (± light cautery), shave excision, electrodesiccation/radiofrequency, CO2/Er:YAG laser, TCA application; topical hydrogen peroxide 40% (FDA approved)", "Dermatosis papulosa nigra: light electrodesiccation/curettage, scissor snip, lasers — caution for PIH in dark skin", "Biopsy if any doubt (melanoma)"]),
 ],
 spot=["Stuck-on waxy verrucous plaque with milia-like cysts and comedo-like openings — SK", "Sudden eruption of SKs — Leser–Trélat"]),

dict(case="Dermatofibroma", src=f"{PYQ}; {IA} (Fibrohistiocytic tumours)",
 qa=[
 ("Write short notes on dermatofibroma (PYQ).", ["Common benign fibrohistiocytic tumour (benign fibrous histiocytoma) — firm, button-like, slightly raised, pink-brown papule/nodule usually on legs of young women; often after minor trauma (insect bite, folliculitis, shaving) — reactive vs clonal debated", "Dimple (Fitzpatrick) sign: lateral compression produces central dimpling because the lesion is tethered to the overlying epidermis"]),
 ("Dermoscopy.", ["Central white scar-like patch with delicate peripheral pigment network (light-brown); dotted vessels; ring-like globules"]),
 ("Histopathology.", ["Ill-defined dermal proliferation of spindle fibroblasts and histiocytes (foam cells, haemosiderin-laden siderophages, Touton giant cells) with collagen trapping at the periphery ('collagen balls'), sparing of a grenz zone", "Overlying epidermis hyperplastic with flat-bottomed elongated pigmented rete ridges ('dirty fingers') and induction of follicular/sebaceous structures (basaloid induction mimicking BCC)", "Factor XIIIa positive, CD34 negative (vs DFSP: CD34 positive, factor XIIIa negative)"]),
 ("Variants.", ["Aneurysmal (haemosiderotic — rapid growth, bluish), cellular (higher recurrence), atypical (pseudosarcomatous), epithelioid, lipidised (ankle), multiple eruptive dermatofibromas (SLE, HIV, immunosuppression)"]),
 ("Differential diagnosis.", ["Dermatofibrosarcoma protuberans (DFSP — larger, growing, multinodular plaque on trunk, CD34+, COL1A1–PDGFB fusion; treat with Mohs/wide excision, imatinib for advanced)", "Melanocytic naevus, melanoma (pigmented DF), keloid/hypertrophic scar, BCC, Kaposi sarcoma, prurigo nodule, epidermoid cyst, Spitz naevus, xanthoma"]),
 ("Enumerate painful skin tumours (PYQ).", ["Mnemonic BLENDAN-GG: Blue rubber bleb naevus, Leiomyoma, Eccrine spiradenoma, Neuroma, Dermatofibroma (sometimes), Angiolipoma, Neurilemmoma (schwannoma), Glomus tumour, Granular cell tumour; also chondrodermatitis nodularis helicis, keloid, endometrioma, calcinosis cutis, MPNST"]),
 ("Management.", ["Reassurance — benign, often persists; excision if symptomatic, enlarging, cosmetically troublesome or diagnostic doubt (scar may be worse than lesion)", "Cryotherapy, intralesional steroids, lasers (flatten/lighten) — partial results"]),
 ],
 spot=["Firm leg papule with positive dimple sign — dermatofibroma", "Factor XIIIa+ / CD34− (DFSP is CD34+)"]),

dict(case="Keloid and hypertrophic scar", src=f"{PYQ}; {IA} (Keloids and hypertrophic scars); International scar management recommendations",
 qa=[
 ("Define and differentiate keloid and hypertrophic scar.", ["Both are abnormal fibroproliferative wound healing with excess collagen", "Hypertrophic scar: raised scar confined to the original wound, appears within weeks, may regress over 1–2 years, common across tension lines/joints (burns), no racial predilection, lower recurrence after excision", "Keloid: extends beyond original wound margins (claw-like), appears months–years after injury (or spontaneously), does not regress, recurs after excision, more in dark skin (Africans, Asians), familial, sites — sternum, shoulders, upper back, earlobes (piercing), mandible; itchy and painful"]),
 ("Pathogenesis.", ["Prolonged inflammation and fibroblast hyperactivity: increased TGF-β1/β2 (decreased TGF-β3), PDGF, VEGF, IL-6; excess type I collagen (keloid) / type III (hypertrophic early); reduced apoptosis, mechanical tension, hypoxia", "Genetic: HLA associations, NEDD4, familial AD forms; hormones (puberty, pregnancy enlarge)"]),
 ("Histopathology.", ["Keloid: thick, hyalinised, eosinophilic glassy collagen bundles ('keloidal collagen') haphazardly arranged, fewer fibroblasts, mucin, no nodules", "Hypertrophic scar: nodules of fine collagen and myofibroblasts (α-SMA+) arranged parallel to the surface, more vessels"]),
 ("Assessment.", ["Vancouver Scar Scale (vascularity, pigmentation, pliability, height), POSAS (Patient and Observer Scar Assessment Scale)"]),
 ("Prevention.", ["Avoid elective surgery/piercing/tattoos in keloid-prone individuals; minimal tension closure along relaxed skin tension lines; early silicone gel/sheets and pressure garments after surgery/burns; prompt treatment of acne"]),
 ("Discuss treatment (combination approach).", ["First line: intralesional triamcinolone acetonide 10–40 mg/ml every 3–4 weeks (side effects — atrophy, hypopigmentation, telangiectasia), silicone gel/sheets (12–24 h/day for months), pressure therapy (earlobe pressure earrings, garments 24–30 mmHg)", "Combined: intralesional 5-FU (with steroid), bleomycin, verapamil; cryotherapy (contact or intralesional cryoprobe) before steroid; botulinum toxin A", "Surgery: excision (intramarginal/core excision) ALWAYS followed by adjuvant therapy (steroids, pressure, radiation) — excision alone has 50–100% recurrence", "Radiotherapy: postoperative superficial X-ray or electron beam/brachytherapy within 24–72 h (recurrent/large keloids in adults)", "Lasers: pulsed-dye laser (erythema, itch), fractional CO2 laser with laser-assisted drug delivery", "Others: imiquimod post-excision, topical/oral tranilast, dupilumab (reports), fat grafting/PRP (hypertrophic)"]),
 ("Discuss relaxed skin tension lines (PYQ).", ["Lines of minimal tension on relaxed skin, perpendicular to underlying muscle pull (follow wrinkles on face — Borges' lines); incisions parallel to RSTL heal with narrow, less noticeable scars and less hypertrophy, vs Langer's lines (cleavage lines on cadavers)"]),
 ],
 spot=["Scar extending beyond wound margins, not regressing, on the sternum/earlobe — keloid", "Excision only with adjuvant (steroid/radiation/pressure)"]),

dict(case="Lipoma", src=f"{PYQ}; {IA} (Tumours of fat)",
 qa=[
 ("What is a lipoma?", ["Commonest soft-tissue tumour: benign, slowly growing, encapsulated tumour of mature adipocytes in subcutis; soft, rubbery, mobile, lobulated, painless swelling with 'slip sign' (edge slips under the palpating finger), skin normal; trunk, neck, upper limbs, adults 40–60 y"]),
 ("Variants.", ["Angiolipoma (multiple small tender subcutaneous nodules in young men, forearms — painful)", "Spindle-cell/pleomorphic lipoma (posterior neck/shoulder of older men)", "Hibernoma (brown fat), lipoblastoma (children), chondroid lipoma, intramuscular lipoma", "Naevus lipomatosus superficialis (Hoffmann–Zurhelle — soft yellowish papules on buttocks/thighs, fat in dermis)", "Lumbosacral lipoma in infants — marker of spinal dysraphism (with dimple, hair tuft, haemangioma — MRI spine)"]),
 ("Syndromes with multiple lipomas.", ["Familial multiple lipomatosis, Madelung's disease (benign symmetric lipomatosis — 'horse-collar' neck fat; alcoholic men), Dercum's disease (adiposis dolorosa — painful lipomas in obese post-menopausal women), Gardner syndrome, Cowden/PTEN hamartoma syndromes, Proteus syndrome, MEN1, Bannayan–Riley–Ruvalcaba, encephalocraniocutaneous lipomatosis"]),
 ("Differential diagnosis.", ["Epidermoid/pilar cyst (punctum, firmer, attached to skin), liposarcoma (large >5 cm, deep, rapidly growing, firm — imaging/biopsy), neurofibroma, angiolipoma, hibernoma, lymph node, hernia, haematoma, abscess, soft-tissue sarcoma, ganglion"]),
 ("Investigations.", ["Clinical; ultrasound (well-circumscribed hyperechoic/isoechoic mass with striations); MRI for large (>5 cm), deep, subfascial, rapidly growing or painful lesions; histology after excision (MDM2 amplification by FISH to distinguish atypical lipomatous tumour/well-differentiated liposarcoma)"]),
 ("Management.", ["Reassurance if small/asymptomatic", "Surgical excision (enucleation through small incision; squeeze technique), liposuction for large/multiple (risk of incomplete removal), intralesional deoxycholic acid or steroid injection (shrinks small lipomas)", "Discuss indications and complications of excisional surgery (PYQ): indications — cosmetic, symptomatic, diagnostic uncertainty; complications — haematoma, seroma, infection, wound dehiscence, nerve injury, recurrence, scar/keloid"]),
 ],
 spot=["Soft lobulated mobile subcutaneous swelling with slip sign — lipoma", "Painful multiple small nodules in young men — angiolipomas", "Lumbosacral lipoma in infant — MRI spine"]),

dict(case="Milium / colloid milium", src=f"{PYQ}; {IA} (Cysts; colloid milium)",
 qa=[
 ("What are milia?", ["Small (1–2 mm), superficial, white-yellow, keratin-filled epidermoid cysts (arising from vellus hair follicles or eccrine ducts) — very common on face (eyelids, cheeks, nose) of all ages, especially newborns (~40–50%)"]),
 ("Classify milia and explain their clinical features (PYQ).", ["Primary: congenital/neonatal (face, palate — Epstein pearls; gingiva — Bohn's nodules; resolve in weeks), benign primary milia in children/adults (eyelids, cheeks), milia en plaque (cluster on erythematous plaque — retroauricular/eyelid), multiple eruptive milia, nodular grouped milia, genodermatoses (Bazex–Dupré–Christol, Rombo, Gorlin, oro-facial-digital syndrome type I, Marie–Unna hypotrichosis, pachyonychia congenita)", "Secondary: after blistering diseases (EB dystrophica, porphyria cutanea tarda, bullous pemphigoid, EBA), trauma, burns, dermabrasion, laser resurfacing, radiotherapy, potent topical steroids (atrophy), drugs (cyclosporine, penicillamine)"]),
 ("Histopathology of milia.", ["Small epidermoid cyst lined by stratified squamous epithelium with granular layer, containing laminated keratin"]),
 ("Treatment of milia.", ["Neonatal: self-resolve — no treatment", "Extraction/de-roofing with a sterile needle or No.11 blade and expression; electrodesiccation, CO2 laser; topical retinoids for multiple; minocycline for milia en plaque"]),
 ("Add a note on colloid milium (PYQ).", ["Rare degenerative condition with deposition of homogeneous eosinophilic 'colloid' material in the papillary dermis giving translucent, yellowish-brown or amber, dome-shaped papules that ooze gelatinous material on puncture", "Types: adult colloid milium (commonest — sun-exposed face, dorsa of hands, neck in middle-aged outdoor workers; chronic UV, petroleum/hydroquinone exposure; derived from elastic fibres/solar elastosis), juvenile colloid milium (before puberty; derived from keratinocytes — keratin; may be familial; associated with ligneous conjunctivitis), nodular colloid degeneration (single nodule, face/trunk), pigmented colloid milium (hydroquinone-related, ochronosis-like)", "Histology: fissured homogeneous eosinophilic material in papillary dermis with clefts, grenz zone; stains weakly with Congo red/PAS (may mimic amyloid); juvenile type keratin-positive", "Differential: lichen/nodular amyloidosis, syringomas, sebaceous hyperplasia, lipoid proteinosis, milia, hydrocystomas, xanthomas, molluscum", "Treatment: photoprotection; dermabrasion, cryotherapy, CO2/Er:YAG/fractional lasers, diathermy, curettage — recurrences common"]),
 ],
 spot=["Tiny white keratin cysts on eyelids — milia", "Translucent amber papules on sun-exposed face oozing gel — colloid milium"]),

dict(case="Pearly penile papules", src=f"{PYQ}; {IA} (Normal variants of genitalia; non-venereal genital lesions)",
 qa=[
 ("What are pearly penile papules (PPP)?", ["Common normal anatomical variant (angiofibromas — hirsuties coronae glandis) in 15–45% of men (more in uncircumcised, young adults): small (1–3 mm), smooth, dome-shaped or filiform, pearly white to skin-coloured papules arranged in one or several symmetrical rows around the corona and sulcus of the glans; asymptomatic, not infectious, not sexually transmitted"]),
 ("Histopathology.", ["Angiofibroma: dense fibrous stroma with stellate fibroblasts and dilated thin-walled vessels covered by normal or slightly thinned epidermis (same as facial angiofibroma)"]),
 ("Discuss non-venereal genital lesions (PYQ).", ["Normal variants: PPP, Fordyce spots (ectopic sebaceous glands — yellow papules on shaft/labia), vestibular papillae (women — symmetrical filiform papules of vestibule; female counterpart of PPP), Tyson's glands, median raphe cysts, angiokeratomas of scrotum (Fordyce)", "Dermatoses: psoriasis, lichen planus (annular on glans), lichen sclerosus (BXO), lichen nitidus, seborrhoeic dermatitis, Zoon's balanitis (plasma cell balanitis — glistening red-orange plaque on glans of uncircumcised elderly), fixed drug eruption, contact dermatitis, candidal balanoposthitis, scabies nodules, vitiligo", "Neoplastic: erythroplasia of Queyrat, bowenoid papulosis, SCC, extramammary Paget's, Kaposi sarcoma"]),
 ("Differential diagnosis.", ["Genital warts (condyloma acuminata — irregular, random distribution, cauliflower surface, acetowhite), molluscum contagiosum (umbilicated, scattered), Fordyce spots (shaft, yellow), sebaceous hyperplasia, lichen nitidus, ectopic sebaceous glands, angiokeratomas"]),
 ("Why does it matter in clinics?", ["Commonly mistaken for genital warts by patients and doctors → anxiety ('venereophobia'), unnecessary destructive treatment; dermoscopy shows uniform papules with central comma/dotted vessels without the mosaic pattern of warts"]),
 ("Management.", ["Reassurance and education (no treatment needed)", "For cosmetic/psychological distress: CO2 laser vaporisation, fractional CO2, pulsed-dye laser, radiofrequency, cryotherapy (variable) — warn about scarring and recurrence"]),
 ],
 spot=["Symmetrical rows of pearly dome papules around the corona — PPP (normal variant, angiofibroma)", "Do not treat as warts"]),

dict(case="Sebaceous hyperplasia", src=f"{PYQ}; {IA} (Sebaceous gland disorders and tumours)",
 qa=[
 ("What is sebaceous hyperplasia?", ["Common benign enlargement of sebaceous glands around a central dilated follicular duct — 2–6 mm soft yellowish papules with central umbilication (dell) on forehead, cheeks, nose of middle-aged/elderly (UV, ageing — reduced androgen-driven turnover)", "Also: neonatal (maternal androgens — tiny yellow papules on nose; resolve), transplant recipients on cyclosporine, familial premature form, juxtaclavicular beaded lines"]),
 ("Discuss the variations of sebaceous glands (PYQ).", ["Ectopic sebaceous glands (not associated with hair follicles): Fordyce spots (lips, buccal mucosa, genitalia), Montgomery tubercles (areola), Tyson's glands (prepuce), Meibomian glands (eyelids), glands of Zeis", "Physiological changes: large in neonates (maternal androgens), small in childhood, enlarge at puberty; reduced in old age", "Disorders: sebaceous hyperplasia, nevus sebaceous, steatocystoma multiplex (cysts with sebaceous lobules in wall — KRT17), sebaceous adenoma/sebaceoma/epithelioma and sebaceous carcinoma (eyelid — aggressive), Muir–Torre syndrome (sebaceous neoplasms + keratoacanthomas + visceral cancers — mismatch repair genes MSH2/MLH1)"]),
 ("Dermoscopy and histopathology.", ["Dermoscopy: yellow-white lobular globules ('cumulus clouds/popcorn') with crown vessels that do not cross the centre (vs arborising vessels crossing the BCC surface)", "Histology: enlarged mature sebaceous lobules arranged around a dilated central duct opening to the surface; no atypia"]),
 ("Differential diagnosis.", ["Nodular BCC (pearly, arborising vessels, slowly growing — biopsy if doubt), sebaceous adenoma (Muir–Torre if multiple/young), molluscum contagiosum, milia, xanthelasma, syringoma, trichoepithelioma, fibrous papule of the nose, colloid milium, rhinophyma (diffuse)"]),
 ("When should you think of Muir–Torre syndrome?", ["Sebaceous adenoma, sebaceoma or sebaceous carcinoma (not ordinary sebaceous hyperplasia), especially if multiple, outside head and neck, or in younger patients — check mismatch repair protein immunohistochemistry (MSH2, MSH6, MLH1, PMS2) and screen for colorectal and other visceral cancers"]),
 ("Treatment.", ["Benign — reassurance", "Light electrodesiccation, cryotherapy, shave excision, curettage, CO2/Er:YAG/pulsed-dye laser, PDT, trichloroacetic acid; oral isotretinoin (low dose) for multiple lesions (relapse after stopping)"]),
 ],
 spot=["Yellow umbilicated papules on forehead of elderly man — sebaceous hyperplasia (crown vessels)", "Sebaceous adenoma → think Muir–Torre"]),
]
